solution:
def fight(hp1, dmg1, hp2, dmg2):
    while True:
        hp2 -= dmg1
        if hp2 <= 0:
            return "P1"
        hp1 -= dmg2
        if hp1 <= 0:
            return "P2"

alt:
def fight(hp1, dmg1, hp2, dmg2):
    turn = 1
    while hp1 > 0 and hp2 > 0:
        if turn == 1:
            hp2 -= dmg1
        else:
            hp1 -= dmg2
        turn = 3 - turn
    return "P1" if hp2 <= 0 else "P2"
